declare const __YUDIA_WEB__: boolean;

/**
 * Website only: install the service worker (sw.js, generated by the website build) that keeps a copy of the app
 * itself, so Yudia opens with no connection and your downloads can be played. It never touches the Jellyfin
 * server's traffic. Not used on the TV (packaged app) or in the dev server.
 */
export function registerOfflineApp() {
  if (typeof __YUDIA_WEB__ === 'undefined' || !__YUDIA_WEB__) return;
  if (!('serviceWorker' in navigator) || !window.isSecureContext) return;
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js').catch((e) => console.warn('[offline] service worker not installed', e));
  });
}
